from PIL import Image
im = Image.open('chess_board.png').convert('RGB')
s = 80

def is_board(p):
    r, g, b = p
    if abs(r-181) < 25 and abs(g-136) < 25 and abs(b-99) < 25:
        return True
    if abs(r-240) < 25 and abs(g-217) < 25 and abs(b-181) < 25:
        return True
    return False

def sig(r, c):
    vals = []
    for i in range(8, 72, 2):
        for j in range(8, 72, 2):
            p = im.getpixel((c*s + j, r*s + i))
            if not is_board(p):
                vals.append(sum(p))
    vals.sort()
    step = max(1, len(vals) // 64)
    out = [sum(vals[k*step:(k+1)*step]) // step for k in range(64)]
    return out

exemplars = {}
for r, c, name in [(0,0,'k'),(0,2,'q'),(0,3,'r'),(0,5,'b'),(1,1,'n'),(1,5,'n'),(1,6,'r')]:
    exemplars[name] = sig(r, c)

def show(r, c):
    q = sig(r, c)
    best = []
    for name, e in exemplars.items():
        d = sum(abs(a-b) for a, b in zip(q, e))
        best.append((d, name))
    best.sort()
    print('abcdefgh'[c] + str(8-r), best[:3])

for r, c in [(0,4),(2,0),(2,2),(2,4),(3,3),(3,5),(3,6),(5,0),(5,2),(6,1),(6,4),(6,5),(6,6),(7,0),(7,2),(7,4),(7,7)]:
    show(r, c)
